  ('d7d25bc1-830a-5dcb-8352-3aca06079b62', '22222222-2222-2222-2222-222222222215', 'mcq', '数列{𝑎𝑛}的前𝑛项和𝑆𝑛= 𝑛2 + 1，则𝑎5的值为( ).', '[{"key": "A", "text": "9"}, {"key": "B", "text": "8"}, {"key": "C", "text": "6"}, {"key": "D", "text": "4"}, {"key": "E", "text": "16"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 4, true, 58, null),
