  ('4a986e41-981b-588c-91f7-e33cf736d290', '22222222-2222-2222-2222-222222222215', 'short', '已知数列𝑎1, 𝑎2, 𝑎3, ⋯, 𝑎10. 则𝑎1 −𝑎2 + 𝑎3 −⋯+ 𝑎9 −𝑎10 ⩾0.', null, '', '', '数学/第5章 数列（1）.pdf', 5, true, 60, null),
