  ('1fb53fcb-f1b5-508b-b214-539d5037f382', '22222222-2222-2222-2222-222222222215', 'short', '𝑎𝑛 2 ⩾𝑎𝑛+1 2 , 𝑛= 1,2, ⋯,9 你的坚持，终将美好！ 4 考点2：等差数列 一、定义 如果一个数列从第2 项起，每一项与它前一项的差等于同一个常数，那么 这个数列就叫作等差数列，这个常数叫做等差数列的公差，公差通常用字 母𝑑表示，即𝑎𝑛+1 −𝑎𝑛= 𝑑 (𝑛∈𝑁+). 特别地，𝑑= 0时，数列为常数列. 二、通项公式', null, '', '', '数学/第5章 数列（1）.pdf', 5, true, 62, null),
  ('44ce7442-fbb5-528a-be6b-4f9092774647', '22222222-2222-2222-2222-222222222215', 'short', '基本公式：𝑎𝑛= 𝑎1 + (𝑛−1)𝑑= 𝑛𝑑+ 𝑎1 −𝑑. 𝑎1 𝑎2 𝑎3 𝑎4 ⋯ 𝑎𝑛−1 𝑎𝑛 𝑎1 + 𝑑 𝑎2 + 𝑑 𝑎3 + 𝑑 ⋯ 𝑎𝑛−2 + 𝑑 𝑎𝑛−1 + 𝑑 𝑎1 + 2𝑑 𝑎1 + 3𝑑 ⋯ 𝑎1 + (𝑛−2)𝑑 𝑎1 + (𝑛−1)𝑑 【注】等差数列通项公式𝒂𝒏可以表示为𝒂𝒏= 𝑨𝒏+ 𝑩，即𝑨≠𝟎时，等差 数列的通项公式可以看做𝒏的一次函数，𝑨是公差.', null, '', '', '数学/第5章 数列（1）.pdf', 6, true, 63, null),
  ('91e08f23-1185-5ab7-a633-8801998959fb', '22222222-2222-2222-2222-222222222215', 'short', '拓展公式：𝑎𝑛= 𝑎𝑘+ (𝑛−𝑘)𝑑. 𝑎1 𝑎2 𝑎3 𝑎4 𝑎5 𝑎6 𝑎7 ⋯ 𝑎1 + 𝑑 𝑎2 + 𝑑 𝑎3 + 𝑑 𝑎4 + 𝑑 𝑎5 + 𝑑 𝑎6 + 𝑑 ⋯ 𝑎1 + 2𝑑 𝑎1 + 3𝑑 𝑎1 + 4𝑑 𝑎1 + 5𝑑 𝑎1 + 6𝑑 ⋯ 你的坚持，终将美好！ 5 题型1：考查等差数列𝒂𝒏的求解', null, '', '', '数学/第5章 数列（1）.pdf', 6, true, 64, null),
  ('d92759c5-3b17-572e-b4ed-1326c58fcede', '22222222-2222-2222-2222-222222222215', 'mcq', '在等差数列{𝑎𝑛}中，𝑎2 = 2, 𝑎3 = 4，则𝑎10 = ( ).', '[{"key": "A", "text": "12"}, {"key": "B", "text": "14"}, {"key": "C", "text": "16"}, {"key": "D", "text": "18"}, {"key": "E", "text": "20"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 7, true, 65, null),
  ('30fecdda-6cc6-5453-883f-343e19d57c0d', '22222222-2222-2222-2222-222222222215', 'mcq', '在等差数列{𝑎𝑛}中，若𝑎1 = 2, 𝑎4 + 𝑎5 = −3，则公差𝑑= ( ).', '[{"key": "A", "text": "−2"}, {"key": "B", "text": "−1"}, {"key": "C", "text": "1"}, {"key": "D", "text": "2"}, {"key": "E", "text": "3"}]'::jsonb, '', '', '数学/第5章 数列（1）.pdf', 7, true, 66, null),
  ('9df7ba60-1e60-570b-a270-9558cccdeaa5', '22222222-2222-2222-2222-222222222215', 'short', '若{𝑎𝑛}为等差数列，则𝑎1𝑎8 < 𝑎4𝑎5.', null, '', '', '数学/第5章 数列（1）.pdf', 8, true, 67, null),
