  ('d9944d9d-1880-53af-80b2-4ef886d87798', '22222222-2222-2222-2222-222222222216', 'short', '等差数列：𝑎𝑛= 𝑎1 + (𝑛−1)𝑑= 𝑎𝑘+ (𝑛−𝑘)𝑑.', null, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 2, null),
